// @FIGURE_CODE_BEGIN
var TMAX = 4 * Math.PI;
var TEAL = '#1B87A8', GRIDC = '#8f8f8f';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var U = 30;

var S = {
  n: 4, sine: false, a: 4, sweep: TMAX,
  custom: false, customFn: null, customSrc: '4*cos(3*theta)',
  highlight: false, compare: true
};

/* ── frame (uniform world scale, extra room at the bottom for captions) ── */
function configureFrame(w, h) {
  w = w || 600; h = h || 450;
  var CW = 12.8, CH = 15.0;
  var u = Math.min(w / CW, h / CH);
  if (!isFinite(u) || u <= 0) u = 30;
  var ex = (w / u - CW) / 2, ey = (h / u - CH) / 2;
  setPlotFrame({
    xDomain: [-6.4 - ex, 6.4 + ex],
    yDomain: [-8.6 - ey, 6.4 + ey],
    margin: 0, draw: draw
  });
  U = u;
}
var f0 = setPlotFrame({ xDomain: [-1, 1], yDomain: [-1, 1], margin: 0, draw: draw });
configureFrame(f0.width, f0.height);
document.addEventListener('fig-resize', function (e) {
  configureFrame(e.detail.width, e.detail.height);
  redraw();
});

/* ── helpers ───────────────────────────────────────────────────────────── */
function fmtNum(v) { var r = Math.round(v * 10) / 10; return (Math.abs(r - Math.round(r)) < 1e-9) ? String(Math.round(r)) : r.toFixed(1); }

function radialOf(o) {
  return function (th) {
    if (o.custom && o.fn) return o.fn(th);
    return o.a * (o.sine ? Math.sin(o.n * th) : Math.cos(o.n * th));
  };
}

function roseSegs(o, t0, t1, cx, cy, sc) {
  var rf = radialOf(o);
  var perUnit = 60 + 16 * (o.custom ? 6 : o.n);
  var N = Math.max(60, Math.round((t1 - t0) * perUnit));
  N = Math.min(N, 2600);
  var segs = [], cur = [];
  for (var i = 0; i <= N; i++) {
    var th = t0 + (t1 - t0) * i / N;
    var r;
    try { r = rf(th); } catch (e) { r = NaN; }
    if (typeof r === 'number' && isFinite(r) && Math.abs(r) <= 6.05) {
      cur.push([cx + sc * r * Math.cos(th), cy - sc * r * Math.sin(th)]);
    } else { if (cur.length > 1) segs.push(cur); cur = []; }
  }
  if (cur.length > 1) segs.push(cur);
  return segs;
}
function ptsAttr(p) { return p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' '); }

function label(g, str, size, italic, x, y, anchorLeft) {
  var t = g.text(str).font({
    family: italic ? 'Georgia, "Times New Roman", serif' : 'Helvetica, Arial, sans-serif',
    size: size, style: italic ? 'italic' : 'normal'
  }).fill(italic ? '#111' : '#3b3b3b');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(1.5, size * 0.22), 'stroke-linejoin': 'round' });
  if (anchorLeft) { t.x(x); t.cy(y); } else { t.center(x, y); }
  return t;
}

function drawAxes(g, cx, cy, sc) {
  var AL = 5.95 * sc, hl = 0.44 * sc, hw = 0.2 * sc, aw = Math.max(0.9, sc * 0.036);
  function ax(dx, dy, tip) {
    var ex = cx + dx * AL, ey = cy + dy * AL;
    g.line(cx, cy, ex - dx * hl * 0.5, ey - dy * hl * 0.5).stroke({ color: '#000', width: aw });
    var nx = -dy, ny = dx;
    var head = g.polygon([
      [ex, ey],
      [ex - dx * hl + nx * hw, ey - dy * hl + ny * hw],
      [ex - dx * hl - nx * hw, ey - dy * hl - ny * hw]
    ]).fill('#000');
    head.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
  }
  ax(1, 0, 'Polar axis: θ = 0 direction');
  ax(-1, 0, 'θ = π direction');
  ax(0, -1, 'θ = π/2 direction');
