// @FIGURE_CODE_BEGIN
var TMAX = 4 * Math.PI;
var TEAL = '#1B87A8', GRIDC = '#8f8f8f';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var U = 30;

var S = {
  n: 4, sine: false, a: 4, sweep: TMAX,
  custom: false, customFn: null, customSrc: '4*cos(3*theta)',
  highlight: false, compare: true
};

/* ── frame (uniform world scale, extra room at the bottom for captions) ── */
function configureFrame(w, h) {
  w = w || 600; h = h || 450;
  var CW = 12.8, CH = 15.0;
  var u = Math.min(w / CW, h / CH);
  if (!isFinite(u) || u <= 0) u = 30;
  var ex = (w / u - CW) / 2, ey = (h / u - CH) / 2;
  setPlotFrame({
    xDomain: [-6.4 - ex, 6.4 + ex],
    yDomain: [-8.6 - ey, 6.4 + ey],
    margin: 0, draw: draw
  });
  U = u;
}
var f0 = setPlotFrame({ xDomain: [-1, 1], yDomain: [-1, 1], margin: 0, draw: draw });
configureFrame(f0.width, f0.height);
document.addEventListener('fig-resize', function (e) {
  configureFrame(e.detail.width, e.detail.height);
  redraw();
});

/* ── helpers ───────────────────────────────────────────────────────────── */
function fmtNum(v) { var r = Math.round(v * 10) / 10; return (Math.abs(r - Math.round(r)) < 1e-9) ? String(Math.round(r)) : r.toFixed(1); }

function radialOf(o) {
  return function (th) {
    if (o.custom && o.fn) return o.fn(th);
    return o.a * (o.sine ? Math.sin(o.n * th) : Math.cos(o.n * th));
  };
}

function roseSegs(o, t0, t1, cx, cy, sc) {
  var rf = radialOf(o);
  var perUnit = 60 + 16 * (o.custom ? 6 : o.n);
  var N = Math.max(60, Math.round((t1 - t0) * perUnit));
  N = Math.min(N, 2600);
  var segs = [], cur = [];
  for (var i = 0; i <= N; i++) {
    var th = t0 + (t1 - t0) * i / N;
    var r;
    try { r = rf(th); } catch (e) { r = NaN; }
    if (typeof r === 'number' && isFinite(r) && Math.abs(r) <= 6.05) {
      cur.push([cx + sc * r * Math.cos(th), cy - sc * r * Math.sin(th)]);
    } else { if (cur.length > 1) segs.push(cur); cur = []; }
  }
  if (cur.length > 1) segs.push(cur);
  return segs;
}
function ptsAttr(p) { return p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' '); }

function label(g, str, size, italic, x, y, anchorLeft) {
  var t = g.text(str).font({
    family: italic ? 'Georgia, "Times New Roman", serif' : 'Helvetica, Arial, sans-serif',
    size: size, style: italic ? 'italic' : 'normal'
  }).fill(italic ? '#111' : '#3b3b3b');
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(1.5, size * 0.22), 'stroke-linejoin': 'round' });
  if (anchorLeft) { t.x(x); t.cy(y); } else { t.center(x, y); }
  return t;
}

function drawAxes(g, cx, cy, sc) {
  var AL = 5.95 * sc, hl = 0.44 * sc, hw = 0.2 * sc, aw = Math.max(0.9, sc * 0.036);
  function ax(dx, dy, tip) {
    var ex = cx + dx * AL, ey = cy + dy * AL;
    g.line(cx, cy, ex - dx * hl * 0.5, ey - dy * hl * 0.5).stroke({ color: '#000', width: aw });
    var nx = -dy, ny = dx;
    var head = g.polygon([
      [ex, ey],
      [ex - dx * hl + nx * hw, ey - dy * hl + ny * hw],
      [ex - dx * hl - nx * hw, ey - dy * hl - ny * hw]
    ]).fill('#000');
    head.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
  }
  ax(1, 0, 'Polar axis: θ = 0 direction');
  ax(-1, 0, 'θ = π direction');
  ax(0, -1, 'θ = π/2 direction');
  ax(0, 1, 'θ = 3π/2 direction');
}

/* ── one polar panel ──────────────────────────────────────────────────── */
function drawPanel(g, cx, cy, sc, o) {
  var lw = Math.max(0.55, sc * 0.022);
  var dash = (lw * 0.7).toFixed(2) + ',' + (lw * 3.6).toFixed(2);

  for (var i = 1; i <= 5; i++) {
    var ring = g.circle(2 * sc * i).center(cx, cy).fill('none')
      .stroke({ color: GRIDC, width: lw, dasharray: dash, linecap: 'round' });
    ring.css('cursor', 'pointer');
    (function (r, el) {
      el.on('mousemove', function (e) { showTooltip('Polar grid ring: r = ' + r, e); })
        .on('mouseleave', hideTooltip);
    })(i, ring);
  }
  var R = 5 * sc;
  [30, 60, 120, 150].forEach(function (d) {
    var th = d * Math.PI / 180;
    g.line(cx - R * Math.cos(th), cy + R * Math.sin(th), cx + R * Math.cos(th), cy - R * Math.sin(th))
      .stroke({ color: GRIDC, width: lw, dasharray: dash, linecap: 'round' });
  });

  if (!o.custom && o.a > 0.05) {
    var env = g.circle(2 * sc * Math.min(o.a, 5.9)).center(cx, cy).fill('none')
      .stroke({ color: '#c4c4c4', width: lw * 1.4 });
    env.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Envelope r = a = ' + fmtNum(o.a) + ': every petal tip touches it', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The amplitude a', 'a is the largest value |r| can reach, so all petals stop on this circle. Changing a stretches the whole rose uniformly; it never adds or removes a petal.');
      });
  }

  drawAxes(g, cx, cy, sc);

  if (o.highlight && !o.custom) {
    var a0 = o.sine ? 0 : -Math.PI / (2 * o.n);
    var a1 = o.sine ? Math.PI / o.n : Math.PI / (2 * o.n);
    var segs = roseSegs(o, a0, a1, cx, cy, sc);
    if (segs.length) {
      var poly = [[cx, cy]].concat(segs[0]);
      var pg = g.polygon(ptsAttr(poly)).fill({ color: TEAL, opacity: 0.18 }).stroke('none');
      pg.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('One petal is generated by a θ-interval of width π/n = ' + (Math.PI / o.n).toFixed(2) + ' rad', e); })
        .on('mouseleave', hideTooltip);
    }
  }

  if (o.ghost && o.sweep < TMAX - 1e-3) {
    roseSegs(o, 0, TMAX, cx, cy, sc).forEach(function (sg) {
      g.polyline(ptsAttr(sg)).fill('none')
        .stroke({ color: TEAL, width: sc * 0.075, opacity: 0.22, linecap: 'round', linejoin: 'round' });
    });
  }

  if (o.sweep > 1e-3) {
    var tip = o.custom
      ? 'r = ' + prettySrc(o.srcText) + '  (custom expression)'
      : 'r = ' + fmtNum(o.a) + (o.sine ? ' sin(' : ' cos(') + o.n + 'θ)  →  ' +
        (o.n % 2 === 0 ? (2 * o.n) + ' petals (n even)' : o.n + ' petals (n odd)');
    roseSegs(o, 0, o.sweep, cx, cy, sc).forEach(function (sg) {
      var pl = g.polyline(ptsAttr(sg)).fill('none')
        .stroke({ color: TEAL, width: sc * 0.105, linecap: 'round', linejoin: 'round' });
      pl.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Why parity decides the count',
            'Over 0 ≤ θ ≤ π the factor cos(nθ) (or sin(nθ)) completes n half-waves, so n petals are drawn. For odd n the next interval π ≤ θ ≤ 2π produces negative r, and a negative radius lands on the ray opposite θ — exactly the petals already drawn, so they are retraced: still n petals. For even n nothing lines up with what exists, so n brand-new petals appear between the old ones, giving 2n.');
        });
    });
  }

  if (o.trace && o.sweep > 1e-3 && o.sweep < TMAX - 1e-3) {
    var rf = radialOf(o), rv;
    try { rv = rf(o.sweep); } catch (e) { rv = NaN; }
    if (isFinite(rv) && Math.abs(rv) <= 6.05) {
      var px = cx + sc * rv * Math.cos(o.sweep), py = cy - sc * rv * Math.sin(o.sweep);
      g.line(cx, cy, px, py).stroke({
        color: TEAL, width: lw * 1.5, dasharray: (sc * 0.12) + ',' + (sc * 0.1)
      });
      var dot = g.circle(sc * 0.3).center(px, py).fill(TEAL);
      dot.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('θ = ' + o.sweep.toFixed(2) + ' rad (' + (o.sweep * 180 / Math.PI).toFixed(0) + '°), r = ' + rv.toFixed(2) +
            (rv < 0 ? '  — negative r plots on the opposite ray' : ''), e);
        })
        .on('mouseleave', hideTooltip);
    }
  }
}

function prettySrc(s) { return String(s).replace(/theta/g, 'θ').replace(/\*/g, ''); }

function formulaStr() {
  if (S.custom && S.customFn) return 'r = ' + prettySrc(S.customSrc);
  return 'r = ' + fmtNum(S.a) + (S.sine ? ' sin(' : ' cos(') + S.n + 'θ)';
}
function badgeStr() {
  if (S.custom && S.customFn) return 'custom r(θ) — predict, then count the petals';
  return (S.n % 2 === 0)
    ? 'n = ' + S.n + ' (even)  →  2n = ' + (2 * S.n) + ' petals'
    : 'n = ' + S.n + ' (odd)  →  n = ' + S.n + ' petals';
}

/* ── full redraw ──────────────────────────────────────────────────────── */
function redraw() {
  draw.clear();
  var g = draw.group();
  if (S.compare) {
    var evenN = (S.n % 2 === 0) ? S.n : Math.min(8, S.n + 1);
    var oddN = (S.n % 2 === 1) ? S.n : Math.max(1, S.n - 1);
    var sc = 0.45 * U;
    var cy = plotY(0.6);
    var panels = [
      { cx: plotX(-3.2), o: { n: evenN, sine: false, a: S.a, sweep: TMAX, custom: false, ghost: false, trace: false, highlight: false }, cap: 'r = ' + fmtNum(S.a) + ' cos(' + evenN + 'θ), n even', tag: '(a)' },
      { cx: plotX(3.2), o: { n: oddN, sine: true, a: S.a, sweep: TMAX, custom: false, ghost: false, trace: false, highlight: false }, cap: 'r = ' + fmtNum(S.a) + ' sin(' + oddN + 'θ), n odd', tag: '(b)' }
    ];
    panels.forEach(function (p) {
      drawPanel(g, p.cx, cy, sc, p.o);
      var y1 = cy + 5 * sc + 0.95 * U;
      label(g, p.cap, 0.52 * U, true, p.cx, y1);
      label(g, (p.o.n % 2 === 0 ? 2 * p.o.n : p.o.n) + ' petals', 0.36 * U, false, p.cx, y1 + 0.62 * U);
      label(g, p.tag, 0.52 * U, true, p.cx, y1 + 1.45 * U);
    });
  } else {
    var o = {
      n: S.n, sine: S.sine, a: S.a, sweep: S.sweep,
      custom: S.custom && !!S.customFn, fn: S.customFn, srcText: S.customSrc,
      ghost: true, trace: true, highlight: S.highlight
    };
    drawPanel(g, plotX(0), plotY(0), U, o);
    var ft = label(g, formulaStr(), 0.66 * U, true, plotX(0), plotY(-6.55));
    ft.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Live formula: a = ' + fmtNum(S.a) + ', n = ' + S.n, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Reading r = a·cos(nθ)', 'a fixes the petal length (the envelope radius). n fixes how fast r oscillates, hence how many petals: n if n is odd, 2n if n is even. Choosing sin instead of cos rotates the whole rose by π/(2n) without changing the count.');
      });
    var bt = label(g, badgeStr(), 0.42 * U, false, plotX(0), plotY(-7.55));
    bt.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Parity rule: odd n → n petals, even n → 2n petals', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The parity rule', 'Counting petals is not memorization: the second half of the θ-sweep either retraces the first half (odd n) or fills the gaps with new petals (even n). Animate the sweep with n = 3 and then n = 4 to watch both cases happen.');
      });
    if (S.sweep < TMAX - 1e-3) {
      label(g, 'θ = ' + S.sweep.toFixed(2) + ' rad = ' + (S.sweep * 180 / Math.PI).toFixed(0) + '°  (of 720°)',
        0.4 * U, false, plotX(-6.2), plotY(5.85), true);
    }
  }
}

/* ── control handlers ─────────────────────────────────────────────────── */
function update_nStep(v) { S.n = Math.round(v); S.custom = false; syncCustomBox(); redraw(); }
function toggle_trigForm(on) { S.sine = !!on; S.custom = false; syncCustomBox(); redraw(); }
function update_amplitude(v) {
