  document.getElementById('thetaSweepVal').value = (v / Math.PI).toFixed(2) + 'π';
}
function update_thetaSweep(v) {
  S.sweep = v; document.getElementById('thetaSweepVal').value = (v / Math.PI).toFixed(2) + 'π';
