// @FIGURE_CODE_BEGIN
var TMAX = 4 * Math.PI;
var TEAL = '#1B87A8', GRIDC = '#8f8f8f';
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

var S = {
  n: 4, sine: false, a: 4, sweep: TMAX,
  custom: false, customFn: null, customSrc: '4*cos(3*theta)',
  highlight: false, compare: true
};
var FW = { w: 600, h: 450 };

/* ── frame: world units == pixels, so plotX/plotY drive every placement ── */
function configureFrame(w, h) {
  FW.w = Math.max(80, w || 600);
  FW.h = Math.max(80, h || 450);
  setPlotFrame({ xDomain: [0, FW.w], yDomain: [0, FW.h], margin: 0, draw: draw });
}
var f0 = setPlotFrame({ xDomain: [0, 1], yDomain: [0, 1], margin: 0, draw: draw });
configureFrame(f0.width, f0.height);
document.addEventListener('fig-resize', function (e) {
  configureFrame(e.detail.width, e.detail.height);
  redraw();
});
function PX(x) { return plotX(x); }
function PY(y) { return plotY(FW.h - y); }

/* ── helpers ───────────────────────────────────────────────────────────── */
function fmtNum(v) {
  var r = Math.round(v * 10) / 10;
  return (Math.abs(r - Math.round(r)) < 1e-9) ? String(Math.round(r)) : r.toFixed(1);
}
function prettySrc(s) { return String(s).replace(/theta/g, 'θ').replace(/\*/g, ''); }

function radialOf(o) {
  return function (th) {
    if (o.custom && o.fn) return o.fn(th);
    return o.a * (o.sine ? Math.sin(o.n * th) : Math.cos(o.n * th));
  };
}
function roseSegs(o, t0, t1, cx, cy, sc) {
  var rf = radialOf(o);
  var perUnit = 70 + 18 * (o.custom ? 6 : o.n);
  var N = Math.min(2800, Math.max(60, Math.round((t1 - t0) * perUnit)));
  var segs = [], cur = [];
  for (var i = 0; i <= N; i++) {
    var th = t0 + (t1 - t0) * i / N, r;
    try { r = rf(th); } catch (e) { r = NaN; }
    if (typeof r === 'number' && isFinite(r) && Math.abs(r) <= 6.4) {
      cur.push([cx + sc * r * Math.cos(th), cy - sc * r * Math.sin(th)]);
    } else { if (cur.length > 1) segs.push(cur); cur = []; }
  }
  if (cur.length > 1) segs.push(cur);
  return segs;
}
function ptsAttr(p) {
  return p.map(function (q) { return q[0].toFixed(2) + ',' + q[1].toFixed(2); }).join(' ');
}

/* italic/upright mixed serif math text, centred at (cx,cy) */
function mathText(g, parts, size, cx, cy) {
  var t = g.text(function (add) {
    parts.forEach(function (p) { add.tspan(p[0]).font({ style: p[1] ? 'italic' : 'normal' }); });
  });
  t.font({ family: 'Georgia, "Times New Roman", serif', size: size, leading: 1 }).fill('#111');
  t.attr({
    'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': Math.max(1.4, size * 0.18), 'stroke-linejoin': 'round'
  });
  t.center(cx, cy);
  return t;
}
function plainText(g, str, size, cx, cy, left) {
  var t = g.text(str).font({ family: 'Helvetica, Arial, sans-serif', size: size }).fill('#3b3b3b');
  t.attr({
    'paint-order': 'stroke', stroke: '#fff',
    'stroke-width': Math.max(1.4, size * 0.2), 'stroke-linejoin': 'round'
  });
  if (left) { t.x(cx); t.cy(cy); } else { t.center(cx, cy); }
  return t;
}

/* ── panel pieces ─────────────────────────────────────────────────────── */
function drawAxes(g, cx, cy, R) {
  var AL = 1.40 * R, hl = 0.135 * R, hw = 0.058 * R, aw = Math.max(1, R * 0.0125);
  function ax(dx, dy, tip) {
    var ex = cx + dx * AL, ey = cy + dy * AL;
    g.line(cx, cy, ex - dx * hl * 0.55, ey - dy * hl * 0.55).stroke({ color: '#000', width: aw });
    var nx = -dy, ny = dx;
    var head = g.polygon([
      [ex, ey],
      [ex - dx * hl + nx * hw, ey - dy * hl + ny * hw],
      [ex - dx * hl - nx * hw, ey - dy * hl - ny * hw]
    ]).fill('#000');
    head.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
  }
  ax(1, 0, 'Polar axis: θ = 0 direction');
  ax(-1, 0, 'θ = π direction');
  ax(0, -1, 'θ = π/2 direction');
  ax(0, 1, 'θ = 3π/2 direction');
}

function drawPanel(g, cx, cy, R, o) {
  var sc = R / 5;
  var lw = Math.max(0.6, R * 0.0075);
  var dash = (lw * 0.95).toFixed(2) + ',' + (lw * 3.6).toFixed(2);

  for (var i = 1; i <= 5; i++) {
    var ring = g.circle(2 * sc * i).center(cx, cy).fill('none')
      .stroke({ color: GRIDC, width: lw, dasharray: dash, linecap: 'round' });
    ring.css('cursor', 'pointer');
    (function (rr, el) {
      el.on('mousemove', function (e) { showTooltip('Polar grid ring: r = ' + rr, e); })
        .on('mouseleave', hideTooltip);
    })(i, ring);
  }
  var RR = 5 * sc;
  [30, 60, 120, 150].forEach(function (d) {
    var th = d * Math.PI / 180;
    g.line(cx - RR * Math.cos(th), cy + RR * Math.sin(th), cx + RR * Math.cos(th), cy - RR * Math.sin(th))
      .stroke({ color: GRIDC, width: lw, dasharray: dash, linecap: 'round' });
  });

  if (o.envelope && !o.custom && o.a > 0.05) {
    var env = g.circle(2 * sc * Math.min(o.a, 5.9)).center(cx, cy).fill('none')
      .stroke({ color: '#c4c4c4', width: lw * 1.5 });
    env.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Envelope r = a = ' + fmtNum(o.a) + ': every petal tip touches it', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The amplitude a', 'a is the largest value |r| can reach, so every petal stops on this circle. Changing a stretches the whole rose uniformly; it never adds or removes a petal.');
      });
  }

  drawAxes(g, cx, cy, R);

  if (o.highlight && !o.custom) {
    var a0 = o.sine ? 0 : -Math.PI / (2 * o.n);
    var a1 = o.sine ? Math.PI / o.n : Math.PI / (2 * o.n);
    var hs = roseSegs(o, a0, a1, cx, cy, sc);
    if (hs.length) {
      var pg = g.polygon(ptsAttr([[cx, cy]].concat(hs[0])))
        .fill({ color: TEAL, opacity: 0.18 }).stroke('none');
      pg.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('One petal is generated by a θ-interval of width π/n = ' + (Math.PI / o.n).toFixed(2) + ' rad', e);
        })
        .on('mouseleave', hideTooltip);
    }
  }

  if (o.ghost && o.sweep < TMAX - 1e-3) {
    roseSegs(o, 0, TMAX, cx, cy, sc).forEach(function (sg) {
      g.polyline(ptsAttr(sg)).fill('none')
        .stroke({ color: TEAL, width: Math.max(1.4, R * 0.034), opacity: 0.22, linecap: 'round', linejoin: 'round' });
    });
  }

  if (o.sweep > 1e-3) {
    var tip = o.custom
      ? 'r = ' + prettySrc(o.srcText) + '  (custom expression)'
      : 'r = ' + fmtNum(o.a) + (o.sine ? ' sin(' : ' cos(') + o.n + 'θ)  →  ' +
      (o.n % 2 === 0 ? (2 * o.n) + ' petals (n even)' : o.n + ' petals (n odd)');
    roseSegs(o, 0, o.sweep, cx, cy, sc).forEach(function (sg) {
      var pl = g.polyline(ptsAttr(sg)).fill('none')
        .stroke({ color: TEAL, width: Math.max(1.8, R * 0.040), linecap: 'round', linejoin: 'round' });
      pl.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(tip, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Why parity decides the count',
            'Over 0 ≤ θ ≤ π the factor cos(nθ) (or sin(nθ)) completes n half-waves, so n petals get drawn. For odd n the next interval π ≤ θ ≤ 2π gives negative r, and a negative radius lands on the ray opposite θ — exactly the petals already there, so they are retraced: still n petals. For even n nothing lines up with what exists, so n brand-new petals appear between the old ones, giving 2n.');
        });
    });
  }

  if (o.trace && o.sweep > 1e-3 && o.sweep < TMAX - 1e-3) {
    var rf = radialOf(o), rv;
    try { rv = rf(o.sweep); } catch (e) { rv = NaN; }
    if (isFinite(rv) && Math.abs(rv) <= 6.4) {
      var pxp = cx + sc * rv * Math.cos(o.sweep), pyp = cy - sc * rv * Math.sin(o.sweep);
      g.line(cx, cy, pxp, pyp).stroke({
        color: TEAL, width: lw * 1.8, dasharray: (R * 0.024) + ',' + (R * 0.02)
      });
      var dot = g.circle(R * 0.058).center(pxp, pyp).fill(TEAL);
      dot.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('θ = ' + o.sweep.toFixed(2) + ' rad (' + (o.sweep * 180 / Math.PI).toFixed(0) + '°), r = ' + rv.toFixed(2) +
            (rv < 0 ? '  — negative r plots on the opposite ray' : ''), e);
        })
        .on('mouseleave', hideTooltip);
    }
  }
}

/* ── captions ─────────────────────────────────────────────────────────── */
function symbolicParts(sine, parity) {
  return [['r', 1], [' = ', 0], ['a', 1], [sine ? 'sin(' : 'cos(', 0], ['n', 1], ['θ', 1], ['), ', 0], ['n', 1], [' ' + parity, 0]];
}
function numericParts() {
  if (S.custom && S.customFn) return [['r', 1], [' = ', 0], [prettySrc(S.customSrc), 1]];
  return [['r', 1], [' = ', 0], [fmtNum(S.a), 1], [S.sine ? ' sin(' : ' cos(', 0], [String(S.n), 1], ['θ', 1], [')', 0]];
}
function badgeStr() {
  if (S.custom && S.customFn) return 'custom r(θ) — predict, then count the petals';
  return (S.n % 2 === 0)
    ? 'n = ' + S.n + ' (even)  →  2n = ' + (2 * S.n) + ' petals'
    : 'n = ' + S.n + ' (odd)  →  n = ' + S.n + ' petals';
}

/* ── full redraw ──────────────────────────────────────────────────────── */
function redraw() {
  draw.clear();
  var g = draw.group();
  var W = FW.w, H = FW.h;

  if (S.compare) {
    var R = Math.min(W / 6.45, H / 3.72);
    var top = (H - 3.72 * R) / 2;
    var cyS = top + 1.42 * R;
    var evenN = (S.n % 2 === 0) ? S.n : Math.min(8, S.n + 1);
    var oddN = (S.n % 2 === 1) ? S.n : Math.max(1, S.n - 1);
    var panels = [
      { dx: -1.585, n: evenN, sine: false, parity: 'even', tag: '(a)' },
      { dx: 1.585, n: oddN, sine: true, parity: 'odd', tag: '(b)' }
    ];
    panels.forEach(function (p) {
      var cxS = W / 2 + p.dx * R;
      var cx = PX(cxS), cy = PY(cyS);
      var o = {
        n: p.n, sine: p.sine, a: S.a, sweep: TMAX,
        custom: false, envelope: false, ghost: false, trace: false, highlight: false
      };
      drawPanel(g, cx, cy, R, o);
      var cap = mathText(g, symbolicParts(p.sine, p.parity), 0.175 * R, cx, PY(cyS + 1.77 * R));
      var count = (p.n % 2 === 0) ? 2 * p.n : p.n;
      cap.css('cursor', 'pointer')
        .on('mousemove', function (e) {
          showTooltip('Here n = ' + p.n + ' (' + p.parity + ') → ' + count + ' petals. Turn off Compare mode for the live numeric formula.', e);
        })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(p.parity === 'even' ? 'Panel (a): n even' : 'Panel (b): n odd',
            p.parity === 'even'
              ? 'With n even the sweep 0 ≤ θ ≤ 2π draws 2n distinct petals: the second half of the sweep has nothing to retrace, so a fresh set of petals appears between the first set.'
              : 'With n odd only n petals appear. Past θ = π the radius goes negative, and a negative radius plots on the opposite ray — right on top of a petal already drawn, so the curve retraces itself.');
        });
      mathText(g, [[p.tag, 0]], 0.175 * R, cx, PY(cyS + 2.11 * R));
    });
  } else {
    var R2 = Math.min(W / 3.1, H / 3.80);
    var top2 = (H - 3.80 * R2) / 2;
    var cy2 = top2 + 1.42 * R2;
    var cxp = PX(W / 2), cyp = PY(cy2);
    var o2 = {
      n: S.n, sine: S.sine, a: S.a, sweep: S.sweep,
      custom: S.custom && !!S.customFn, fn: S.customFn, srcText: S.customSrc,
      envelope: true, ghost: true, trace: true, highlight: S.highlight
    };
    drawPanel(g, cxp, cyp, R2, o2);

    var ft = mathText(g, numericParts(), 0.175 * R2, cxp, PY(cy2 + 1.72 * R2));
    ft.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Live formula: a = ' + fmtNum(S.a) + ', n = ' + S.n, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Reading r = a·cos(nθ)', 'a fixes the petal length (the envelope radius). n fixes how fast r oscillates, hence how many petals: n if n is odd, 2n if n is even. Choosing sin instead of cos rotates the whole rose by π/(2n) without changing the count.');
      });
    var bt = plainText(g, badgeStr(), 0.115 * R2, cxp, PY(cy2 + 2.12 * R2));
    bt.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Parity rule: odd n → n petals, even n → 2n petals', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The parity rule', 'Counting petals is not memorization: the second half of the θ-sweep either retraces the first half (odd n) or fills the gaps with new petals (even n). Animate the sweep with n = 3 and then n = 4 to watch both cases happen.');
      });
    if (S.sweep < TMAX - 1e-3) {
      plainText(g, 'θ = ' + S.sweep.toFixed(2) + ' rad = ' + (S.sweep * 180 / Math.PI).toFixed(0) + '°  (of 720°)',
        0.115 * R2, PX(0.02 * W), PY(H - 0.05 * H), true);
    }
  }
}

/* ── control handlers ─────────────────────────────────────────────────── */
function leaveCompare() {
  if (S.compare) { S.compare = false; document.getElementById('compareInput').checked = false; }
}
function syncCustomBox() { document.getElementById('customInput').checked = !!S.custom; }

function update_nStep(v) { S.n = Math.round(v); S.custom = false; syncCustomBox(); redraw(); }
function toggle_trigForm(on) { S.sine = !!on; S.custom = false; syncCustomBox(); redraw(); }
function update_amplitude(v) {
  S.a = v; document.getElementById('amplitudeVal').value = v.toFixed(1);
  S.custom = false; syncCustomBox(); redraw();
}
function setSweepUI(v) {
  document.getElementById('thetaSweepInput').value = v;
  document.getElementById('thetaSweepVal').value = (v / Math.PI).toFixed(2) + 'π';
}
function update_thetaSweep(v) {
  S.sweep = v; document.getElementById('thetaSweepVal').value = (v / Math.PI).toFixed(2) + 'π';
  leaveCompare(); redraw();
}
function toggle_highlight(on) { S.highlight = !!on; if (on) leaveCompare(); redraw(); }
function toggle_compare(on) { S.compare = !!on; redraw(); }
function toggle_custom(on) {
  S.custom = !!on && !!S.customFn;
  if (S.custom) leaveCompare();
  syncCustomBox(); redraw();
}

var animT = null;
function trigger_animate() {
  if (animT) { cancelAnimationFrame(animT); animT = null; }
  leaveCompare();
  var start = performance.now(), dur = 6500;
  function frame(t) {
    var k = Math.min(1, (t - start) / dur);
    S.sweep = k * TMAX;
    setSweepUI(S.sweep);
    redraw();
    animT = (k < 1) ? requestAnimationFrame(frame) : null;
  }
  animT = requestAnimationFrame(frame);
}

/* ── equation input (scaffold owns parsing) ───────────────────────────── */
var eqFirst = true;
bindEquationInput('rThetaInput', function (fn, src) {
  S.customFn = fn; S.customSrc = src;
  if (eqFirst) { eqFirst = false; }
  else { S.custom = true; leaveCompare(); syncCustomBox(); }
  redraw();
}, { variables: ['theta'] });

/* ── demo step player ─────────────────────────────────────────────────── */
var steps = [
  { title: 'Start with one petal', narration: 'With n = 1 the curve r = a cos(θ) is a single circular petal along the polar axis. This is the simplest rose and the baseline for counting.', state: { n: 1, sine: false, a: 4, sweep: TMAX } },
  { title: 'Odd n: three petals', narration: 'Set n = 3 and three petals appear, not six. The trace stops at θ = 2π; slide it back and watch: after θ = π the curve simply retraces the same three petals, because negative r flips the point onto a ray already used.', state: { n: 3, sine: false, a: 4, sweep: 6.283 } },
  { title: 'Even n: petal count doubles', narration: 'Now n = 4 — the curve from panel (a). Eight petals fill the circle: four along the axes and four on the diagonals. Nothing is retraced, so the count is 2n.', state: { n: 4, sine: false, a: 4, sweep: TMAX } },
  { title: 'Sine rotates, it does not recount', narration: 'Toggle to the sine form with n = 3 to reproduce panel (b): still three petals, but the rose has rotated by π/(2n) so one petal points straight down. Orientation and parity are separate ideas.', state: { n: 3, sine: true, a: 4, sweep: TMAX } },
  { title: 'a changes size only', narration: 'Drag the amplitude down and every petal shortens to the new maximum radius a, all together — the gray envelope circle shrinks with them. Three petals stay three petals: a scales the rose, n counts it.', state: { n: 3, sine: true, a: 1.5, sweep: TMAX } },
  { title: 'Test the rule yourself', narration: 'Step to a large even n, then type your own r(θ) in the equation box. Predict the petal count before the graph redraws — and try a non-integer n to see the rose fail to close.', state: { n: 6, sine: false, a: 4, sweep: TMAX } }
];
var stepIdx = -1;

function syncUI() {
  document.getElementById('nStepInput').value = S.n;
  document.getElementById('nStepVal').value = S.n;
  document.getElementById('trigFormInput').checked = S.sine;
  document.getElementById('amplitudeInput').value = S.a;
  document.getElementById('amplitudeVal').value = S.a.toFixed(1);
  setSweepUI(S.sweep);
  document.getElementById('highlightInput').checked = S.highlight;
  document.getElementById('compareInput').checked = S.compare;
  syncCustomBox();
}

function applyStep(i) {
  if (animT) { cancelAnimationFrame(animT); animT = null; }
  stepIdx = Math.max(-1, Math.min(steps.length - 1, i));
  if (stepIdx < 0) {
    S.n = 4; S.sine = false; S.a = 4; S.sweep = TMAX;
    S.custom = false; S.highlight = false; S.compare = true;
    document.getElementById('stepLabel').textContent = 'Overview — the textbook figure';
    document.getElementById('demoNarration').textContent =
      'The original figure: (a) r = a cos(nθ) with n even draws 2n petals — here 8; (b) r = a sin(nθ) with n odd draws only n — here 3. Press ▶ to see why the parity of n, not the trig function, sets the count.';
  } else {
    var st = steps[stepIdx];
    S.n = st.state.n; S.sine = st.state.sine; S.a = st.state.a; S.sweep = st.state.sweep;
    S.custom = false; S.compare = false;
    document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + '/' + steps.length + ': ' + st.title;
    document.getElementById('demoNarration').textContent = st.narration;
  }
  syncUI();
  redraw();
}
function nextStep() { applyStep(stepIdx + 1 > steps.length - 1 ? -1 : stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1 < -1 ? steps.length - 1 : stepIdx - 1); }

applyStep(-1);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are building an educational interactive figure for a textbook. The goal is a guided demo that helps students understand the concept — not just a static reconstruction.

OUTPUT: respond with ONLY these two complete marker-wrapped sections. The JavaScript section must be non-empty and must draw visible graphics:
